-- sort_order 201: ゴミの分別とリサイクル  answer=1
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT 'ゴミの分別とリサイクル', E'日本では自治体によってゴミの分別方法が異なるため、引っ越した際に困る人も多い。燃えるゴミ・燃えないゴミ・資源ゴミ・粗大ゴミなど、細かく分類して指定の曜日に出さなければならない。\nリサイクルの目的は、資源の有効活用と廃棄物の削減である。ペットボトルはキャップとラベルを外して洗い、つぶしてから出すのが基本だ。缶や瓶も同様に、軽くすすいで種類別に分ける必要がある。\nしかし現実には、面倒だという理由で分別を怠る人も少なくない。適切に分別されないゴミは、リサイクルの効率を下げるだけでなく、処理施設のトラブルの原因にもなる。ゴミの分別は個人の手間がかかる行為だが、環境を守るための大切な取り組みである。地域のルールをしっかり確認し、正しく分別する習慣を身につけることが求められる。', 'article', 'N2', 310, '[]'::jsonb,
  '{"question":"本文の内容と合うものはどれか。","options":["日本全国で統一されたゴミ分別のルールが定められている。","ゴミを正しく分別しないと、処理施設のトラブルの原因になることがある。","ペットボトルはキャップをつけたままリサイクルに出してよい。","粗大ゴミは毎週決まった曜日に回収される。"],"answer":1}'::jsonb, 201
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='ゴミの分別とリサイクル');

-- sort_order 202: テレワークの普及と課題  answer=0
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT 'テレワークの普及と課題', E'新型コロナウイルスの感染拡大をきっかけに、多くの企業でテレワーク（在宅勤務）が急速に普及した。通勤時間がなくなり、育児や介護と仕事を両立しやすくなるなど、働く人にとってのメリットは大きい。また、企業側もオフィスの維持費を削減できるという利点がある。\n一方で、テレワークには課題も多い。自宅では仕事とプライベートの境界があいまいになり、長時間働いてしまう人もいる。また、同僚とのコミュニケーションが減ることで、孤独感を感じたり、チームワークが損なわれたりするケースも報告されている。\n特に新入社員にとっては、先輩から直接指導を受ける機会が減るため、スキルの習得が遅れるという問題がある。テレワークの利点を生かしながら、こうした課題にどう対応するかが、これからの企業に求められる重要な経営課題となっている。', 'article', 'N2', 320, '[]'::jsonb,
  '{"question":"本文でテレワークのメリットとして挙げられているものはどれか。","options":["通勤時間がなくなり、育児や介護と仕事を両立しやすくなる。","新入社員が先輩から直接指導を受けやすくなる。","社員同士のコミュニケーションが増え、チームワークが向上する。","自宅では仕事に集中しやすく、生産性が必ず上がる。"],"answer":0}'::jsonb, 202
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='テレワークの普及と課題');

-- sort_order 203: 図書館の役割  answer=3
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '図書館の役割', E'公共図書館は、地域住民が無料で本を借りたり、調べ物をしたりできる施設である。かつては蔵書の貸し出しが主な機能であったが、近年はその役割が大きく変わってきた。\n現代の図書館では、インターネット端末の利用や、地域の歴史・文化に関するアーカイブの公開なども行われている。さらに、子どもへの読み聞かせイベントや、就職活動を支援するセミナーなど、コミュニティの交流拠点としての機能も担うようになった。\nデジタル化の進展により「本はネットで読める時代に図書館は必要か」という議論も起きているが、図書館には誰もが平等に知識へアクセスできる「知の公共インフラ」という意義がある。経済的な事情にかかわらず、すべての人が情報や文化に触れられる場所として、図書館は今後も重要な役割を果たし続けるだろう。', 'essay', 'N2', 305, '[]'::jsonb,
  '{"question":"本文における図書館の説明として正しいものはどれか。","options":["図書館はデジタル化により、近年その役割が失われてきている。","現代の図書館では本の貸し出しのみを行っている。","就職活動のセミナーは図書館では行えないとされている。","現代の図書館はコミュニティの交流拠点としての機能も担っている。"],"answer":3}'::jsonb, 203
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='図書館の役割');

-- sort_order 204: 食品ロスの問題  answer=2
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '食品ロスの問題', E'食品ロスとは、まだ食べられるのに捨てられてしまう食品のことをいう。日本では年間約600万トンもの食品が廃棄されており、これは世界全体の食料援助量に匹敵する量だという。\n食品ロスが生じる原因はさまざまである。店側では、見た目が悪い規格外品の廃棄や、売れ残り商品の処分が多い。家庭では、買い過ぎや食べ残し、賞味期限・消費期限への誤解が主な原因とされている。賞味期限はあくまでも「おいしく食べられる期限」であり、過ぎたからといって直ちに食べられなくなるわけではない。\nこの問題を解決するため、政府や自治体、企業が連携して「もったいない」意識の普及に取り組んでいる。消費者一人ひとりが必要な分だけ買い、正しい保存方法を実践することが、食品ロス削減への近道である。', 'article', 'N2', 315, '[]'::jsonb,
  '{"question":"本文における賞味期限の説明として正しいものはどれか。","options":["賞味期限を過ぎた食品は、直ちに食べるのをやめなければならない。","賞味期限は食品を安全に食べられる最終期限のことである。","賞味期限はおいしく食べられる期限であり、過ぎても直ちに食べられなくなるわけではない。","賞味期限が近い食品は店側が必ず廃棄しなければならない。"],"answer":2}'::jsonb, 204
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='食品ロスの問題');

