INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '地域ボランティア活動', E'近年、地域社会でのボランティア活動への関心が高まっている。公園の清掃・高齢者の買い物支援・子どもの見守りなど、地域の課題を住民同士で助け合って解決しようとする動きが各地に広がっている。\nボランティア活動の意義は、社会貢献だけにとどまらない。参加者自身も、新しい人との出会いや達成感を通じて、生きがいや充実感を得られるという側面がある。特に定年退職後の高齢者にとって、社会とのつながりを保つ手段として重要視されている。\n一方、ボランティア活動を継続するうえでの課題もある。参加者の固定化や高齢化により、活動の担い手が不足しているケースが多い。若い世代の参加を促すため、SNSを活用した情報発信や、短時間で参加できる仕組みづくりが求められている。地域のつながりを強めるためにも、より多くの人が気軽に参加できる環境の整備が必要だ。', 'article', 'N2', 320, '[]'::jsonb,
  '{"question":"本文でボランティア活動の意義として述べられているものはどれか。","options":["社会貢献に加え、参加者自身も生きがいや充実感を得られる。","定年退職後の高齢者だけが参加できる活動である。","ボランティアに参加すれば、地域の課題はすべて解決できる。","若い世代の参加率が現在すでに高く、後継者不足は解消されている。"],"answer":0}'::jsonb, 205
