-- sort_order 208: SNSと情報リテラシー  answer=3
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT 'SNSと情報リテラシー', E'スマートフォンの普及により、SNS（ソーシャル・ネットワーキング・サービス）は日常生活に欠かせないコミュニケーションツールとなった。情報収集・人間関係の維持・趣味のコミュニティへの参加など、その用途は多岐にわたる。\nしかしSNSには問題点もある。誰でも自由に情報を発信できるため、誤った情報や根拠のないうわさが急速に拡散することがある。こうした「フェイクニュース」や「デマ」は、社会的な混乱や特定の個人・集団への差別・偏見を引き起こす危険性がある。\nSNSを正しく利用するためには、情報リテラシー（情報を批判的に読み取る力）が不可欠である。受け取った情報を鵜呑みにせず、発信元を確認し、複数の情報源と照らし合わせる習慣を持つことが大切だ。また、自分が情報を発信する際も、相手を傷つけないか・事実確認ができているかを慎重に考える必要がある。', 'essay', 'N2', 325, '[]'::jsonb,
  '{"question":"本文で情報リテラシーとして述べられているものはどれか。","options":["SNSに毎日投稿して情報を積極的に発信する力","フォロワーを増やして影響力を高める技術","複数のSNSアカウントを使い分ける方法","情報を批判的に読み取り、発信元や事実を確認する習慣"],"answer":3}'::jsonb, 208
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='SNSと情報リテラシー');

-- sort_order 209: 日本の住宅事情  answer=1
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '日本の住宅事情', E'日本では、都市部を中心に住宅の価格が高騰しており、若い世代にとってマイホームを持つことが難しくなっている。東京・大阪・名古屋などの大都市では、駅近の物件は特に人気が高く、家賃も高水準が続いている。\n一方、地方では人口減少により空き家が増加している。総務省の調査によると、全国の空き家率は約13パーセントに達しており、利活用されないまま放置される物件が社会問題となっている。古い空き家は景観を損なうだけでなく、倒壊の危険や犯罪の温床になる恐れもある。\nこうした状況に対し、自治体の中には空き家を安価に提供する「空き家バンク」を設け、移住希望者と所有者をマッチングさせる取り組みを始めているところもある。都市の住宅不足と地方の空き家問題を同時に解決する方策として、リモートワークの普及に伴う地方移住の促進が注目されている。', 'article', 'N2', 330, '[]'::jsonb,
  '{"question":"地方の空き家問題の説明として本文と合うものはどれか。","options":["空き家率はすでに30パーセントを超えている。","放置された空き家は景観悪化や倒壊の危険、犯罪の温床になる恐れがある。","自治体は空き家を取り壊すことを法律で義務づけている。","地方の空き家はリゾート施設として活用されることが多い。"],"answer":1}'::jsonb, 209
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='日本の住宅事情');

