INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '環境にやさしい買い物', E'2020年7月から日本ではレジ袋の有料化が義務づけられた。これはプラスチックごみの削減を目的とした取り組みの一つであり、エコバッグの持参が広く定着するきっかけとなった。\n環境への配慮という点では、買い物の仕方そのものを見直すことも重要だ。必要な量だけ購入し、過剰包装を断り、詰め替え商品を選ぶといった行動が、廃棄物の削減につながる。また、地元で生産された食品を選ぶ「地産地消」は、輸送にかかるCO2排出量を減らす効果もある。\nただし、消費者だけに負担を求めるだけでは限界がある。企業側もプラスチックの使用量を減らした包装の開発や、リサイクルしやすい素材の採用など、製品の設計段階から環境への影響を考慮することが求められている。環境問題は消費者と企業が協力して取り組むべき課題である。', 'article', 'N2', 315, '[]'::jsonb,
