-- sort_order 213: 災害への備え  answer=1
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '災害への備え', E'日本は地震・台風・豪雨・津波など、さまざまな自然災害が発生しやすい国である。そのため、日頃からの備えが非常に重要とされている。\n家庭での災害対策として、まず非常用持ち出し袋の準備が挙げられる。飲料水・食料・懐中電灯・救急用品・携帯ラジオなどを入れ、いつでも持って逃げられるようにしておく。また、家具の転倒防止グッズの活用や、避難場所・避難経路の事前確認も欠かせない。\n地域コミュニティの協力も重要だ。高齢者や障害のある人など、一人では避難が難しい人を近所で助け合う「共助」の仕組みが各地で整備されつつある。「自助・共助・公助」の3つを組み合わせることで、より効果的な災害対応が可能になる。日頃から地域のつながりを大切にし、いざというときに備えておくことが大切だ。', 'article', 'N2', 325, '[]'::jsonb,
  '{"question":"本文で非常用持ち出し袋に入れるものとして挙げられているものはどれか。","options":["パソコンとスマートフォン","飲料水・食料・懐中電灯・救急用品・携帯ラジオ","現金と貴金属","着替えと寝袋"],"answer":1}'::jsonb, 213
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='災害への備え');

-- sort_order 214: 子育て支援政策  answer=0
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT '子育て支援政策', E'日本では少子化が深刻な社会問題となっており、政府は子育て支援の充実を重要政策の一つとして位置づけている。育児休業の取得促進・保育所の整備・児童手当の拡充など、さまざまな施策が打ち出されてきた。\nとりわけ近年注目されているのが、父親の育児参加を促す「父親育休」の推進である。従来、育児は主に母親が担う傾向があったが、父親も積極的に育休を取得することで、家庭内の役割分担を見直すきっかけになると期待されている。2022年には「産後パパ育休」制度が創設され、子どもの誕生直後に父親が休暇を取りやすくなった。\nしかし、制度があっても実際に育休を取得できない父親も多い。職場の雰囲気や上司の理解不足、業務の多忙さなどが障壁となっている。制度の整備だけでなく、職場文化の変革と社会全体の意識改革が伴わなければ、少子化対策の効果は限定的にとどまってしまう。', 'article', 'N2', 335, '[]'::jsonb,
  '{"question":"本文で「父親育休」に期待されていることとして述べられているのはどれか。","options":["家庭内の役割分担を見直すきっかけになること","少子化問題がすぐに解決されること","母親が職場に早期復帰できるようになること","保育所の待機児童問題が解消されること"],"answer":0}'::jsonb, 214
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='子育て支援政策');

-- sort_order 215: インターネットショッピングの広がり  answer=2
INSERT INTO jlpt_reading_passages (title, passage, passage_type, jlpt_level, word_count, vocabulary_notes, comprehension, sort_order)
SELECT 'インターネットショッピングの広がり', E'インターネットの普及とスマートフォンの浸透により、オンラインショッピングを利用する人が急増している。自宅にいながら24時間いつでも商品を購入でき、価格比較も容易であることから、衣類・食品・家電・書籍など幅広いジャンルの商品がオンラインで購入されるようになった。\nオンラインショッピングの普及は、消費者にとっては利便性の向上をもたらす一方、実店舗にとっては大きな打撃となっている。特に地方の商店街では、顧客がオンラインに流れることで閉店を余儀なくされる店舗が増え、地域の活気が失われるという問題が起きている。\nオンラインと実店舗にはそれぞれ利点がある。実物を手に取って確認できること・その場で入手できること・店員に相談できることなど、実店舗ならではの価値は今も根強い。消費者のニーズに合わせてオンラインと実店舗をうまく組み合わせる「オムニチャネル」戦略が、小売業において重要視されるようになってきている。', 'article', 'N2', 335, '[]'::jsonb,
  '{"question":"本文でオンラインショッピング普及の問題点として述べられているものはどれか。","options":["商品の価格が実店舗よりも高くなること","スマートフォンを持っていない人が買い物できなくなること","地方の商店街で閉店を余儀なくされる店舗が増え、地域の活気が失われること","配送に時間がかかるため消費者の不満が高まること"],"answer":2}'::jsonb, 215
WHERE NOT EXISTS (SELECT 1 FROM jlpt_reading_passages WHERE title='インターネットショッピングの広がり');
